from collections import Counter,deque
def denoise(grid):
 h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
 seen=set(); rects=[]
 for r in range(h):
  for c in range(w):
   color=grid[r][c]
   if color==bg or (r,c) in seen: continue
   q=deque([(r,c)]);seen.add((r,c));cells=[]
   while q:
    y,x=q.popleft();cells.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
      seen.add((yy,xx));q.append((yy,xx))
   a=min(y for y,x in cells);b=max(y for y,x in cells);l=min(x for y,x in cells);rr=max(x for y,x in cells); area=(b-a+1)*(rr-l+1)
   if area>=6 and len(cells)/area>=.70:
    rects.append((color,a,b,l,rr,len(cells),area))
 out=[[bg]*w for _ in range(h)]
 for color,a,b,l,rr,n,area in rects:
  for y in range(a,b+1):
   for x in range(l,rr+1):out[y][x]=color
 return out,rects
